const renderCache = new Map();
let publicDemoCredentials=null;
function renderDemoHint(){
  if(!publicDemoCredentials)return;
  document.querySelector('.login-card small').textContent=`${language==='en'?'Public read-only demo':'Javni demo za čitanje'}: ${publicDemoCredentials.username} / ${publicDemoCredentials.password}`;
}
function notificationText(notification){
  if(language==='sr')return notification.message;
  const split=notification.message.lastIndexOf(' · '),prefix=notification.message.slice(0,split+3),suffix=notification.message.slice(split+3);
  if(split<0)return notification.message;
  let translated=t(suffix);
  if(notification.type==='policy_expired')translated=suffix.replace(/^istekla pre (\d+) dana$/,'expired $1 days ago');
  if(notification.type==='policy_expiring')translated=suffix.replace(/^još (\d+) dana$/,'$1 days remaining');
  if(notification.type==='claim_pending')translated=suffix.replace(/^(\d+) dana u statusu (.+)$/,(_,days,status)=>`${days} days in status ${t(status)}`);
  return prefix+translated;
}
function renderHealth(health){
  renderCache.set(renderHealth,[health]);
  $('#db-status').textContent=t(health.database==='arango'?'ArangoDB aktivan':'Demo režim');
  $('#db-name').textContent=health.database==='arango'?`${language==='en'?'Database':'Baza'}: ${health.databaseName}`:t('Podaci u memoriji');
}
const $=s=>document.querySelector(s),charts={},colors=['#ff6b35','#112f4a','#39a88e','#f2b84b','#7b6ee6','#e85d75'];let claimStatuses=[],kpiData=null;
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[character]));
const chartColor=index=>colors[index]||`hsl(${(index*57)%360} 62% 53%)`;
const doughnutPercentLabels={id:'doughnutPercentLabels',afterDatasetsDraw(chart){
  const values=chart.data.datasets[0].data,total=values.reduce((sum,value)=>sum+value,0);
  if(!total)return;
  const{ctx}=chart;ctx.save();ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#fff';ctx.font='700 11px DM Sans';
  chart.getDatasetMeta(0).data.forEach((arc,index)=>{if(!values[index])return;const point=arc.tooltipPosition();ctx.fillText(`${(values[index]*100/total).toFixed(1)}%`,point.x,point.y)});ctx.restore();
}};
async function api(url,options){const r=await fetch(url,options),d=r.status===204?null:await r.json();if(r.status===401)showLogin();if(!r.ok)throw Error(t(d?.message||'Zahtev nije uspeo.'));return d}
function message(s,text,error=false){const e=$(s);e.textContent=t(text);e.classList.toggle('error',error);setTimeout(()=>{if(e.textContent===t(text))e.textContent=''},3500)}
function stats(d){renderCache.set(stats, Array.from(arguments));const a=[[t('Korisnici'),d.totalClients,t('Ukupno aktivnih polisa'),'↗'],[t('Prosečna starost'),d.averageAge,t('godina'),'◎'],[t('Vodeća kuća'),d.topInsurer.name,`${d.topInsurer.count}${t(" osiguranika")}`,'◆'],[t('Najjači mesec'),t(d.busiestMonth.month),`${d.busiestMonth.count}${t(" putnih polisa")}`,'▦'],[t('Putno osiguranje'),`${d.travelShare}%`,t('ukupnog portfolija'),'✦']];$('#stats-grid').innerHTML=a.map(x=>`<article class="stat"><i>${x[3]}</i><div><span>${x[0]}</span><strong>${x[1]}</strong><small>${x[2]}</small></div></article>`).join('')}
function make(id,type,data,options,plugins=[]){charts[id]?.destroy();charts[id]=new Chart(document.getElementById(id),{type,data,options:{responsive:true,maintainAspectRatio:false,...options},plugins})}
function draw(d){renderCache.set(draw, Array.from(arguments));
  make('travel-chart','line',{labels:d.monthlyTravelSales.map(x=>t(x.month)),datasets:[{data:d.monthlyTravelSales.map(x=>x.count),borderColor:colors[0],backgroundColor:'#ff6b3518',fill:true,tension:.38}]},{scales:{y:{beginAtZero:true,ticks:{precision:0}}},plugins:{legend:{display:false}}});
  const insurerTotal=d.insurerDistribution.reduce((sum,item)=>sum+item.count,0);
  make('insurer-chart','doughnut',{labels:d.insurerDistribution.map(x=>x.name),datasets:[{data:d.insurerDistribution.map(x=>x.count),backgroundColor:d.insurerDistribution.map((x,index)=>chartColor(index)),borderWidth:4}]},{cutout:'60%',plugins:{legend:{position:'bottom'},tooltip:{callbacks:{label:context=>{const value=context.raw,percent=insurerTotal?value*100/insurerTotal:0;return`${context.label}: ${value} ${t("osiguranika")} (${percent.toFixed(1)}%)`}}}}},[doughnutPercentLabels]);
  make('avg-age-chart','bar',{labels:d.avgAgeByInsurance.map(x=>t(x.type)),datasets:[{data:d.avgAgeByInsurance.map(x=>x.avgAge),backgroundColor:colors,borderRadius:7}]},{scales:{y:{beginAtZero:true}},plugins:{legend:{display:false}}});
  make('july-travel-chart','bar',{labels:d.julyTravelSales.map(x=>`${x.day} ${language==='en'?'Jul':'jul'}`),datasets:[{label:t('Putne polise'),data:d.julyTravelSales.map(x=>x.count),backgroundColor:d.julyTravelSales.map(x=>x.count?'#ff6b35':'#e9edef'),borderRadius:5,maxBarThickness:24}]},{scales:{y:{beginAtZero:true,ticks:{precision:0}},x:{grid:{display:false},ticks:{maxRotation:0,autoSkip:true,maxTicksLimit:16}}},plugins:{legend:{display:false},tooltip:{callbacks:{title:items=>items[0].label,label:context=>`${context.raw} ${context.raw===1?t('polisa'):t('polise')}`}}}});
  make('age-policy-chart','scatter',{datasets:[{label:t('Broj polisa po starosti'),data:d.ageDistribution,backgroundColor:'#39a88e',borderColor:'#177f6b',pointRadius:6,pointHoverRadius:9}]},{scales:{x:{type:'linear',title:{display:true,text:t('Starost korisnika (godine)')},ticks:{precision:0}},y:{beginAtZero:true,title:{display:true,text:t('Broj zaključenih polisa')},ticks:{precision:0}}},plugins:{legend:{display:false},tooltip:{callbacks:{label:context=>`${context.raw.x} ${t("godina")}: ${context.raw.y}${t(" polisa")}`}}}});
  make('type-chart','bar',{labels:d.insuranceTypes.map(x=>x.type),datasets:[{data:d.insuranceTypes.map(x=>x.count),backgroundColor:colors,borderRadius:7}]},{indexAxis:'y',scales:{x:{beginAtZero:true,ticks:{precision:0}}},plugins:{legend:{display:false}}})
}
function drawKpis(data,requestedCurrency){renderCache.set(drawKpis, Array.from(arguments));
  kpiData=data;const select=$('#kpi-currency'),currency=data.currencies.includes(requestedCurrency)?requestedCurrency:data.currencies[0]||'RSD';select.innerHTML=data.currencies.map(item=>`<option${item===currency?' selected':''}>${escapeHtml(item)}</option>`).join('');const kpi=data.byCurrency.find(item=>item.currency===currency)||{writtenPremium:0,collectedPremium:0,outstandingPremium:0,collectionRate:0,claimExposure:0,estimatedLossRatio:0,claimFrequency:0,claimSeverity:0,averagePremium:0,cancellationRate:0},growth=data.growth.find(item=>item.currency===currency)||{},money=value=>`${Number(value).toLocaleString(locale(),{maximumFractionDigits:2})} ${currency}`,percent=value=>value===null||value===undefined?'N/A':`${Number(value).toLocaleString(locale())}%`,cards=[[t('Written premium'),money(kpi.writtenPremium),`${kpi.policyCount||0}${t(" polisa")}`],[t('Collected premium'),money(kpi.collectedPremium),t('evidentirana naplata')],[t('Outstanding premium'),money(kpi.outstandingPremium),t('preostalo za naplatu')],[t('Collection rate'),percent(kpi.collectionRate),t('naplaćeno / ugovoreno')],[t('Claim exposure'),money(kpi.claimExposure),`${kpi.claimCount||0}${t(" šteta")}`],[t('Estimated loss ratio'),percent(kpi.estimatedLossRatio),t('procenjene štete / premija')],[t('Claim frequency'),percent(kpi.claimFrequency),t('polise sa štetom')],[t('Claim severity'),money(kpi.claimSeverity),t('prosečna procenjena šteta')],[t('Average premium'),money(kpi.averagePremium),t('prosek po polisi')],[t('Cancellation rate'),percent(kpi.cancellationRate),t('otkazane police')],[t('MoM growth'),percent(growth.monthOverMonth),growth.currentMonth||t('nema perioda')],[t('YoY growth'),percent(growth.yearOverYear),growth.currentMonth||t('nema perioda')]];$('#kpi-cards').innerHTML=cards.map(item=>`<article class="kpi-card"><span>${item[0]}</span><strong>${item[1]}</strong><small>${item[2]}</small></article>`).join('');
  const trend=data.monthlyTrend.find(item=>item.currency===currency)?.points||[];make('premium-trend-chart','line',{labels:trend.map(item=>item.month),datasets:[{label:t('Written premium'),data:trend.map(item=>item.writtenPremium),borderColor:'#ff6b35',backgroundColor:'#ff6b3520',fill:true,tension:.3},{label:t('Collected premium'),data:trend.map(item=>item.collectedPremium),borderColor:'#39a88e',backgroundColor:'#39a88e20',fill:true,tension:.3}]},{scales:{y:{beginAtZero:true,title:{display:true,text:currency}}},plugins:{legend:{position:'bottom'},tooltip:{callbacks:{label:context=>`${context.dataset.label}: ${Number(context.raw).toLocaleString(locale())} ${currency}`}}}});
  const insurers=data.insurerPerformance.filter(item=>item.currency===currency);make('insurer-kpi-chart','bar',{labels:insurers.map(item=>item.insurer),datasets:[{label:t('Collection rate'),data:insurers.map(item=>item.collectionRate),backgroundColor:'#39a88e',borderRadius:5},{label:t('Estimated loss ratio'),data:insurers.map(item=>item.estimatedLossRatio),backgroundColor:'#e76f51',borderRadius:5}]},{scales:{y:{beginAtZero:true,title:{display:true,text:t('Procenat (%)')}}},plugins:{legend:{position:'bottom'}}})
}
function clients(a){renderCache.set(clients, Array.from(arguments));$('#client-count').textContent=`${a.length}${t(" korisnika")}`;$('#clients-body').innerHTML=[...a].reverse().slice(0,10).map(x=>{let details=escapeHtml(x.insuredSubject||'—');if(x.insuranceType==='Putno'&&x.passportNumber)details=`${escapeHtml(x.destination)}<small class="travel-meta">${t("Pasoš: ")}${escapeHtml(x.passportNumber)} · JMBG: •••••••••${escapeHtml(x.jmbg?.slice(-4))}</small>`;if(x.insuranceType==='Auto'&&x.vehicleMake)details=`${escapeHtml(x.vehicleMake)} · ${x.engineCapacity} cm³<small class="travel-meta">${escapeHtml(t(x.vehicleType))}${x.bodyType?` · ${escapeHtml(t(x.bodyType))}`:''}</small>`;const policy=`<strong>${escapeHtml(x.policyNumber||t('Legacy polisa'))}</strong>${x.insurerPolicyNumber?`<small class="travel-meta">${t('Broj polise osiguravača')}: ${escapeHtml(x.insurerPolicyNumber)}</small>`:''}<small class="travel-meta">${escapeHtml(t(x.policyStatus||'Aktivna'))} · ${Number(x.premium||0).toLocaleString(locale())} ${escapeHtml(x.currency||'RSD')}</small><small class="travel-meta">${escapeHtml(x.validFrom||x.saleDate)} — ${escapeHtml(x.validUntil||'—')} · ${escapeHtml(t(x.paymentStatus||'—'))}</small><small class="travel-meta">${t('Donosilac polise')}: ${escapeHtml(x.policyIntroducer||'—')}</small><a class="policy-pdf-download" data-policy-pdf href="/api/clients/${encodeURIComponent(x.id)}/policy.pdf">${t("Preuzmi PDF")}</a>`;let broker='—';if(x.insuranceType==='Auto'&&x.vehicleMake)broker=x.brokerApproval?.status==='confirmed'?`<span class="broker-confirmed">${t("Potvrđeno")}</span><small class="travel-meta">${escapeHtml(x.brokerApproval.confirmedBy?.displayName||'Broker')}</small>`:['admin','agent','broker'].includes(currentUser?.role)?`<button class="broker-button" data-broker-client="${escapeHtml(x.id)}">${t("Potvrdi broker")}</button>`:`<span class="broker-pending">${t("Na čekanju")}</span>`;return`<tr><td><i class="avatar">${escapeHtml(x.name[0])}${escapeHtml(x.surname[0])}</i><strong>${escapeHtml(x.name)} ${escapeHtml(x.surname)}</strong></td><td>${x.age}</td><td><span class="tag">${escapeHtml(t(x.insuranceType))}</span></td><td>${escapeHtml(x.insurer)}</td><td>${policy}</td><td>${details}</td><td>${broker}</td><td>${new Date(x.saleDate+'T00:00:00').toLocaleDateString(locale())}</td></tr>`}).join('')}
function policyOptions(a){renderCache.set(policyOptions, Array.from(arguments));for(const selector of['#claim-client-select','#payment-client-select','#document-client-select']){const select=$(selector),selected=select.value,records=selector==='#payment-client-select'?a.filter(x=>x.paymentStatus!=='Plaćeno'):a;select.innerHTML=records.map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.policyNumber)} · ${escapeHtml(x.name)} ${escapeHtml(x.surname)} · ${escapeHtml(t(x.insuranceType))} · ${Number(x.premium).toLocaleString(locale())} ${escapeHtml(x.currency)}</option>`).join('')||`<option value="" disabled>${t("Nema dostupnih polisa")}</option>`;if([...select.options].some(option=>option.value===selected))select.value=selected}}
function claims(a){renderCache.set(claims, Array.from(arguments));$('#claim-count').textContent=`${a.length}${t(" prijavljenih šteta")}`;const canWrite=['admin','agent','broker'].includes(currentUser?.role);$('#claims-body').innerHTML=a.map(x=>{const action=canWrite?`<select class="claim-status" data-claim-status="${escapeHtml(x.id)}">${claimStatuses.map(status=>`<option value="${escapeHtml(status)}"${status===x.status?' selected':''}>${escapeHtml(t(status))}</option>`).join('')}</select><button class="secondary claim-action" data-save-claim="${escapeHtml(x.id)}">${t("Sačuvaj")}</button>`:'—';return`<tr><td><strong>${escapeHtml(x.claimNumber)}</strong></td><td>${escapeHtml(x.policyNumber)}<small class="travel-meta">${escapeHtml(x.clientName)}</small></td><td>${new Date(x.incidentDate+'T00:00:00').toLocaleDateString(locale())}<small class="travel-meta">${escapeHtml(x.description)}</small></td><td>${Number(x.estimatedAmount).toLocaleString(locale())} ${escapeHtml(x.currency)}</td><td><span class="status-pill">${escapeHtml(t(x.status))}</span></td><td>${escapeHtml(x.createdBy?.displayName||'—')}</td><td${canWrite?'':' hidden'}>${action}</td></tr>`}).join('')||`<tr><td colspan="7">${t("Nema prijavljenih šteta.")}</td></tr>`}
function payments(a){renderCache.set(payments, Array.from(arguments));$('#payment-count').textContent=`${a.length}${t(" evidentiranih uplata")}`;$('#payments-body').innerHTML=a.map(x=>`<tr><td><strong>${escapeHtml(x.receiptNumber)}</strong></td><td>${escapeHtml(x.policyNumber)}<small class="travel-meta">${escapeHtml(x.clientName)}</small></td><td>${new Date(x.paymentDate+'T00:00:00').toLocaleDateString(locale())}</td><td><strong>${Number(x.amount).toLocaleString(locale())} ${escapeHtml(x.currency)}</strong></td><td>${escapeHtml(t(x.method))}</td><td class="payment-reference">${escapeHtml(x.reference||'—')}</td><td>${escapeHtml(x.recordedBy?.displayName||'—')}</td></tr>`).join('')||`<tr><td colspan="7">${t("Nema evidentiranih uplata.")}</td></tr>`}
function notifications(a){renderCache.set(notifications, Array.from(arguments));$('#notification-count').textContent=`${a.length}${t(" aktivnih")}`;$('#notification-list').innerHTML=a.map(x=>`<article class="notification ${escapeHtml(x.severity)}"><span class="notification-icon">!</span><div><strong>${escapeHtml(t(x.title))}</strong><small>${escapeHtml(notificationText(x))}</small></div><button class="notification-dismiss" data-dismiss-notification="${escapeHtml(x.key)}" title="${t('Označi kao pročitano')}">${t("Pročitano")}</button></article>`).join('')||`<div class="panel notification-empty">${t("Nema aktivnih obaveštenja.")}</div>`}
function documents(a){renderCache.set(documents, Array.from(arguments));$('#document-count').textContent=`${a.length}${t(" dokumenata")}`;$('#documents-body').innerHTML=a.map(x=>`<tr><td><strong>${escapeHtml(x.originalName)}</strong></td><td>${escapeHtml(x.policyNumber)}<small class="travel-meta">${escapeHtml(x.clientName)}</small></td><td>${escapeHtml(x.mimeType)}</td><td>${(x.size/1024).toLocaleString(locale(),{maximumFractionDigits:1})} KB</td><td>${escapeHtml(x.uploadedBy?.displayName||'—')}</td><td>${new Date(x.uploadedAt).toLocaleString(locale())}</td><td><a class="document-download" href="/api/documents/${encodeURIComponent(x.id)}/download">${t("Preuzmi")}</a></td></tr>`).join('')||`<tr><td colspan="7">${t("Nema dodatih dokumenata.")}</td></tr>`}
function etlRuns(a){renderCache.set(etlRuns, Array.from(arguments));$('#etl-runs-body').innerHTML=a.map(x=>`<tr><td>${new Date(x.completedAt).toLocaleString(locale())}</td><td><strong>${escapeHtml(x.initiatedBy?.displayName||'—')}</strong><small class="travel-meta">${escapeHtml(x.initiatedBy?.role||'—')}</small></td><td>${x.extractedRecords}</td><td>${x.transformedRows}</td><td>${x.qualityIssues}</td><td>${x.durationMs} ms</td></tr>`).join('')||`<tr><td colspan="6">${t("ETL još nije pokretan.")}</td></tr>`}
function etlFilters(){return Object.fromEntries([...new FormData($('#etl-form'))].filter(([,value])=>value))}
function etlSummary(run){renderCache.set(etlSummary, Array.from(arguments));$('#etl-summary').innerHTML=[[t('Izvučeno'),run.extractedRecords,t('izvornih slogova')],[t('Transformisano'),run.transformedRows,t('analitičkih redova')],[t('Problemi kvaliteta'),run.qualityIssues,run.rejectedRecords?t('zahteva proveru'):t('dataset je čist')],[t('Trajanje'),`${run.durationMs} ms`,t('ETL izvršavanje')]].map((item,index)=>`<article><span>${item[0]}</span><strong>${item[1]}</strong><small class="${index===2?(run.qualityIssues?'etl-quality-warning':'etl-quality-ok'):''}">${item[2]}</small></article>`).join('')}
function dataQuality(data){renderCache.set(dataQuality, Array.from(arguments));const status=$('#quality-status');status.textContent=`Overall ${data.overallScore}% · ${data.status.toUpperCase()}`;status.className=`badge quality-${data.status}`;$('#quality-updated').textContent=`${data.totalRecords} ${language==='en'?'records · Last ETL':'slogova · Poslednji ETL'}: ${data.lastSuccessfulEtl?new Date(data.lastSuccessfulEtl).toLocaleString(locale()):t('nije pokrenut')}`;$('#quality-dimensions').innerHTML=data.dimensions.map(item=>{const freshness=item.key==='freshness',display=item.value===null?'N/A':`${item.value}${freshness?t(' dana'):'%'}`,progress=freshness?(item.value===null?0:Math.max(0,100-item.value*100/item.target)):item.value,target=freshness?`${language==='en'?'target':'cilj'} ≤ ${item.target}${t(" dana")}`:`${language==='en'?'target':'cilj'} ≥ ${item.target}%`;return`<article class="quality-dimension ${escapeHtml(item.status)}"><header><span>${escapeHtml(t(item.label))}</span><em>${escapeHtml(item.status)}</em></header><strong>${display}</strong><div class="quality-progress"><i style="width:${Math.min(100,Math.max(0,progress))}%"></i></div><span>${target}</span></article>`}).join('');const distribution=data.issueDistribution.length?data.issueDistribution:[{type:'no_issues',count:1}];make('quality-issues-chart','doughnut',{labels:distribution.map(item=>item.type.replaceAll('_',' ')),datasets:[{data:distribution.map(item=>item.count),backgroundColor:distribution.map((item,index)=>chartColor(index)),borderWidth:3}]},{plugins:{legend:{position:'bottom'}}});make('quality-trend-chart','line',{labels:data.trend.map(item=>new Date(item.completedAt).toLocaleDateString(locale())),datasets:[{label:t('Overall score'),data:data.trend.map(item=>item.overallScore),borderColor:'#7b6ee6',backgroundColor:'#7b6ee620',fill:true,tension:.25,pointRadius:5}]},{scales:{y:{min:0,max:100,title:{display:true,text:t('Quality score (%)')}}},plugins:{legend:{display:false}}});$('#quality-issues-body').innerHTML=data.issues.map(item=>`<tr><td><span class="quality-severity ${escapeHtml(item.severity)}">${escapeHtml(item.severity)}</span></td><td>${escapeHtml(item.issue_type)}</td><td>${escapeHtml(item.entity_type)}</td><td>${escapeHtml(item.reference)}</td><td>${escapeHtml(item.detail)}</td></tr>`).join('')||`<tr><td colspan="5">${t("Nema pronađenih problema kvaliteta.")}</td></tr>`}
async function loadEtlWorkspace(){ensureWarehousePanel();const[runs,quality,warehouseState]=await Promise.all([api('/api/etl/runs'),api('/api/analytics/data-quality'),api('/api/warehouse/status')]);etlRuns(runs);dataQuality(quality);warehouseStatus(warehouseState)}
let clientPage=1,clientRequest=0;
function initializeClientFilters(){const cloneOptions=(source,target,empty)=>{$(target).innerHTML=`<option value="">${t(empty)}</option>`+[...$(source).options].map(option=>`<option value="${escapeHtml(option.value)}">${escapeHtml(t(option.textContent))}</option>`).join('')};cloneOptions('#type-select','#client-type-filter','Svi tipovi');cloneOptions('#insurer-select','#client-insurer-filter','Sve kuće');cloneOptions('#policy-status-select','#client-status-filter','Svi statusi');cloneOptions('#payment-status-select','#client-payment-filter','Svi statusi');const sort=$('#client-filters [name="sortBy"]');sort.insertAdjacentHTML('afterbegin',`<option value="createdAt">${t('Najnovije dodato')}</option>`);sort.value='createdAt'}
async function loadClientDirectory(page=clientPage){const request=++clientRequest,params=new URLSearchParams(new FormData($('#client-filters')));params.set('page',page);try{const result=await api(`/api/clients?${params}`);if(request!==clientRequest)return;clientPage=result.pagination.page;clients([...result.items].reverse());$('#client-count').textContent=`${result.pagination.totalItems}${t(" korisnika")}`;$('#client-page-info').textContent=`${t('Stranica')} ${result.pagination.page} / ${result.pagination.totalPages}`;$('#client-prev').disabled=!result.pagination.hasPrevious;$('#client-next').disabled=!result.pagination.hasNext}catch(error){console.error(error)}}
async function refresh(){const[d,k,c,h,cl,p,n,docs]=await Promise.all([api('/api/analytics'),api('/api/analytics/kpis'),api('/api/clients'),api('/api/health'),api('/api/claims'),api('/api/payments'),api('/api/notifications'),api('/api/documents')]);stats(d);draw(d);drawKpis(k,$('#kpi-currency').value);policyOptions(c);claims(cl);payments(p);notifications(n);documents(docs);renderHealth(h);await Promise.all([loadClientDirectory(),loadQuotes()]);if(['admin','analyst'].includes(currentUser?.role))await loadEtlWorkspace();if(currentUser?.role==='admin')await loadLoginAttempts()}
async function options(){const[i,c]=await Promise.all([api('/api/insurers'),api('/api/config')]);claimStatuses=c.claimStatuses;$('#insurer-select').innerHTML=i.map(x=>`<option>${escapeHtml(x.name)}</option>`).join('');$('#etl-insurer').innerHTML=`<option value="">${t("Sve kuće")}</option>`+i.map(x=>`<option>${escapeHtml(x.name)}</option>`).join('');$('#type-select').innerHTML=c.insuranceTypes.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(t(x))}</option>`).join('');$('#etl-type').innerHTML=`<option value="">${t("Svi tipovi")}</option>`+c.insuranceTypes.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(t(x))}</option>`).join('');$('#etl-policy-status').innerHTML=`<option value="">${t("Svi statusi")}</option>`+c.policyStatuses.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(t(x))}</option>`).join('');$('#vehicle-type-select').innerHTML=c.vehicleTypes.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(t(x))}</option>`).join('');$('#body-type-select').innerHTML=c.bodyTypes.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(t(x))}</option>`).join('');$('#currency-select').innerHTML=c.currencies.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(t(x))}</option>`).join('');$('#claim-currency-select').innerHTML=c.currencies.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(t(x))}</option>`).join('');$('#policy-status-select').innerHTML=c.policyStatuses.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(t(x))}</option>`).join('');$('#payment-method-select').innerHTML=c.paymentMethods.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(t(x))}</option>`).join('');$('#payment-method-entry').innerHTML=c.paymentMethods.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(t(x))}</option>`).join('');$('#payment-status-select').innerHTML=c.paymentStatuses.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(t(x))}</option>`).join('');toggleConditionalFields()}
function setConditionalFields(selector,visible){document.querySelectorAll(selector).forEach(label=>{label.hidden=!visible;const control=label.querySelector('input,select');control.required=visible;if(!visible)control.value=''})}
