async function changeTemporaryPassword(event){event.preventDefault();const button=event.submitter,data=Object.fromEntries(new FormData(event.target));if(data.newPassword!==data.confirmPassword){message('#password-message','Nove lozinke se ne podudaraju.',true);return}button.disabled=true;try{const result=await api('/api/auth/change-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({currentPassword:data.currentPassword,newPassword:data.newPassword})});event.target.reset();$('#password-screen').hidden=true;await enterApplication(result.user)}catch(error){message('#password-message',error.message,true)}finally{button.disabled=false}}
